/** App 353 の data / deps / scan（T = loadToolkit() の戻り値） */
function inputs353(T) {
  const { KTDevBase, KTDeps, KTScan } = T;
  const raw = { fields: APP353.fields, layout: APP353.layout, views: APP353.views, status: APP353.status, generalNotify: APP353.notifGeneral, perRecordNotify: APP353.notifPerRecord, reminderNotify: APP353.notifReminder, actions: APP353.actions, customize: APP353.customize, settings: APP353.settings, appAcl: null, recordAcl: null, fieldAcl: null, reports: null, appPlugins: null };
  const data = KTDevBase.dataFrom(raw, { appId: APP353.appId });
  const deps = KTDeps.buildDependencyData(data, KTDeps.normalizeFields(data.fields));
  const files = APP353.customizeFiles.map(f => ({ name: f.name, target: f.plat, kind: f.kind, text: f.text }));
  const scan = KTScan.buildPayload({ appId: APP353.appId, fields: KTScan.fieldList(data.fields, data.layout), files, deps, scannedAt: '2026-10-04T05:18:43.049Z', source: 'preview' });
  KTDeps.mergeScannerEdges(deps, scan);
  return { data, deps, scan, incoming: null };
}
